<?php
require_once 'config/guidance.php';require_once 'config/pdf.php';require_login();$uid=(int)current_user()['id'];$lines=['CAREER COMPASS - PERSONAL GUIDANCE REPORT','Prepared: '.gmdate('Y-m-d').' UTC','For career exploration only. Not an admission decision, aptitude test or employment forecast. Keep this report private.'];
$id=max(0,(int)($_GET['plan']??0));if($id){$q=db()->prepare('SELECT * FROM career_plans WHERE id=? AND user_id=?');$q->execute([$id,$uid]);$p=$q->fetch();if(!$p){http_response_code(404);exit('Plan not found.');}$lines[]='Career goal: '.$p['career_title'];$lines[]=$p['goal'];foreach(json_array($p['roadmap']) as $key=>$value)$lines[]=strtoupper($key)."\n".$value;$q=db()->prepare('SELECT * FROM roadmap_milestones WHERE plan_id=? ORDER BY id');$q->execute([$id]);foreach($q->fetchAll() as $m)$lines[]=($m['completed_at']?'[Complete] ':'[In progress] ').$m['title'].'; due '.($m['due_date']??'not set');}else{$a=latest_assessment($uid);if($a){$lines[]='Latest exploratory interest profile: '.$a['top_interest'].'; '.$a['taken_at'];foreach(json_array($a['riasec_scores']) as $d=>$score)$lines[]=$d.': '.$score.' (mean response / 5 x 100, not a percentile)';}$q=db()->prepare('SELECT r.* FROM recommendations r JOIN recommendation_details d ON d.recommendation_id=r.id WHERE r.user_id=? AND d.run_id=(SELECT MAX(id) FROM recommendation_runs WHERE user_id=?) ORDER BY r.match_score DESC');$q->execute([$uid,$uid]);foreach($q->fetchAll() as $r){$lines[]=$r['career_title'].' - approximate weighted match '.$r['match_score'].'%';$lines[]=$r['explanation'];$lines[]='Useful subjects: '.$r['recommended_subjects'];}$q=db()->prepare('SELECT * FROM saved_items WHERE user_id=? ORDER BY item_type,title');$q->execute([$uid]);foreach($q->fetchAll() as $r)$lines[]='Saved '.$r['item_type'].': '.$r['title'];}
$pdf=guidance_pdf($lines);header('Content-Type: application/pdf');header('Content-Disposition: attachment; filename="career-compass-guidance.pdf"');header('Content-Length: '.strlen($pdf));echo $pdf;
